int cmp(const void* a, const void* b) {
    return (*(int*) a) - (*(int*) b);
}

void getResult(int n, int nums[]) {
    qsort(nums, n, sizeof(int), cmp);

    int min = nums[0];

    int correctSum = min;
    int faultSum = min;

    for(int i=1; i<n; i++) {
        correctSum += nums[i];
        faultSum ^= nums[i];
    }

    if(faultSum == 0) {
        printf("%d\n", correctSum - min);
    } else {
        puts("-1");
    }
}
